import{_ as e,o as d,c as o,a2 as a}from"./chunks/framework.BUwdTBzS.js";const g=JSON.parse('{"title":"工作上下文规范","description":"","frontmatter":{"title":"工作上下文规范"},"headers":[],"relativePath":"dev-flow/references/working-context.md","filePath":"dev-flow/references/working-context.md","lastUpdated":null}'),s={name:"dev-flow/references/working-context.md"};function i(c,t,r,n,l,h){return d(),o("div",null,[...t[0]||(t[0]=[a('<blockquote><p>📄 本页由源文件 <code>skills/dev-flow/references/working-context.md</code> 自动投影生成（单一权威源）。请勿直接编辑本页。</p></blockquote><h1 id="工作上下文规范" tabindex="-1">工作上下文规范 <a class="header-anchor" href="#工作上下文规范" aria-label="Permalink to &quot;工作上下文规范&quot;">​</a></h1><blockquote><p>本文件定义工作上下文的<strong>规则、字段语义、命名/创建/更新流程</strong>。 <strong>完整文件模板</strong> → <code>references/templates/working-context.tpl.md</code>（创建新文件前必须 <code>read_file</code> 加载）。 <strong>设计原则</strong>：模板和规则分离——模板回答&quot;长什么样&quot;，本文件回答&quot;怎么用、怎么改、怎么校验&quot;。</p></blockquote><hr><h2 id="一、命名规则" tabindex="-1">一、命名规则 <a class="header-anchor" href="#一、命名规则" aria-label="Permalink to &quot;一、命名规则&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>~/.codebuddy/working-context/{YYYYMMDD}_{需求简述}_{项目缩写}.md</span></span></code></pre></div><ul><li><strong>格式</strong>：<code>日期_需求简述_项目缩写</code>（需求简述使用英文短横线，禁止中文/驼峰/下划线）</li><li><strong>项目缩写</strong>：按 §六 项目缩写映射表取值，新项目首次使用时 AI 推断并让用户确认后追加映射表</li><li><strong>跨项目需求</strong>：涉及多项目修复时，项目缩写统一使用 <strong><code>crossProject</code></strong>（跨项目专用标识，见 <code>references/cross-project-flow.md</code> §三），不再使用单一项目的缩写</li><li><strong>创建位置</strong>：<code>~/.codebuddy/working-context/</code>（用户目录），严禁创建在项目目录下</li><li><strong>唯一性</strong>：同一需求只允许一个文件，覆盖式更新，流程结束后自动清理</li><li><strong>示例</strong>：<code>20260305_article-list-filter_myProject.md</code>（单项目）/ <code>20260401_fix-login-bug_crossProject.md</code>（跨项目）</li></ul><h3 id="_1-1-文件名功能段对齐规则-v3-2026-05-18" tabindex="-1">1.1 文件名功能段对齐规则（v3，2026-05-18） <a class="header-anchor" href="#_1-1-文件名功能段对齐规则-v3-2026-05-18" aria-label="Permalink to &quot;1.1 文件名功能段对齐规则（v3，2026-05-18）&quot;">​</a></h3><p>工作上下文文件名的「需求简述」段与 YAML <code>branch</code> 字段的「功能段」<strong>必须对齐</strong>：</p><table tabindex="0"><thead><tr><th>YAML 字段</th><th>提取段</th><th>示例</th><th>文件名简述</th></tr></thead><tbody><tr><td><code>branch: feature/article-list-filter</code></td><td>去掉前缀后的最后段</td><td><code>article-list-filter</code></td><td>✅ 一致</td></tr><tr><td><code>branch_dev: feature_dev/article-list-filter/{username}</code></td><td>中间段（不含开发者用户名）</td><td><code>article-list-filter</code></td><td>✅ 一致</td></tr></tbody></table><p><strong>三阶段写入时机</strong>：</p><table tabindex="0"><thead><tr><th>阶段</th><th>处理</th></tr></thead><tbody><tr><td>阶段 0 创建（分支未定稿）</td><td>临时简述，YAML <code>branch: &quot;&quot;</code></td></tr><tr><td>步骤 4 §4.1 分支定稿后</td><td>与分支功能段不一致时<strong>一次性重命名</strong>（仅此一次）</td></tr><tr><td>后续所有迭代/跨分支</td><td><strong>禁止重命名</strong>（文件名稳定锚点 &gt; 易变载体分支）</td></tr></tbody></table><p><strong>重命名脚本</strong>：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 步骤 4 §4.1 分支定稿时执行（如名称不匹配）</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.codebuddy/working-context/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$OLD_FILE </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">~/.codebuddy/working-context/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$NEW_FILE</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.codebuddy/working-context/.active-flows/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">${OLD_FILE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">%</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.md}</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.flow</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">~/.codebuddy/working-context/.active-flows/${</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">NEW_FILE%.md}.flow</span></span></code></pre></div><h3 id="_1-2-反查工具" tabindex="-1">1.2 反查工具 <a class="header-anchor" href="#_1-2-反查工具" aria-label="Permalink to &quot;1.2 反查工具&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 当不确定当前分支对应哪个工作上下文文件时</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.codebuddy/skills/dev-flow/scripts/find-context-by-branch.sh</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [分支名]</span></span></code></pre></div><p>匹配优先级：① YAML <code>branch</code>/<code>branch_dev</code>/<code>branch_workspace</code> 精确匹配 → ② 文件名功能段匹配 → ③ kebab-case 模糊匹配。</p><hr><h2 id="二、yaml-front-matter-字段定义" tabindex="-1">二、YAML Front Matter 字段定义 <a class="header-anchor" href="#二、yaml-front-matter-字段定义" aria-label="Permalink to &quot;二、YAML Front Matter 字段定义&quot;">​</a></h2><blockquote><p>完整 YAML 模板 → <code>templates/working-context.tpl.md</code> §「YAML Front Matter」。本节仅列字段语义和必填性。</p></blockquote><table tabindex="0"><thead><tr><th>字段</th><th>类型</th><th style="text-align:center;">必填</th><th>说明</th></tr></thead><tbody><tr><td><code>mode</code></td><td>string</td><td style="text-align:center;">✅</td><td>基础模式：<code>standard</code> / <code>full</code> / <code>micro-fix</code> / <code>iteration-fix</code> / <code>batch</code> / <code>cross-project</code></td></tr><tr><td><code>current_step</code></td><td>number/string</td><td style="text-align:center;">✅</td><td>当前步骤编号（如 <code>1</code>、<code>4.5</code>、<code>10</code>、<code>done</code>）</td></tr><tr><td><code>status</code></td><td>string</td><td style="text-align:center;">✅</td><td><code>in_progress</code> / <code>completed</code> / <code>blocked</code> / <code>paused</code> / <code>batch_in_progress</code></td></tr><tr><td><code>iteration</code></td><td>number</td><td style="text-align:center;">✅</td><td>迭代轮次（首轮 1，迭代修复时递增）</td></tr><tr><td><code>interaction_mode</code></td><td>string</td><td style="text-align:center;">✅</td><td><code>standard</code> / <code>streamlined</code></td></tr><tr><td><code>complexity</code></td><td>string</td><td style="text-align:center;"></td><td><code>simple</code> / <code>medium</code> / <code>complex</code></td></tr><tr><td><code>branch</code></td><td>string</td><td style="text-align:center;">✅</td><td>父分支名（步骤 4 §4.1 定稿后写入；之前为空字符串）</td></tr><tr><td><code>branch_dev</code></td><td>string</td><td style="text-align:center;">✅</td><td>孙分支名（feature/ 场景为 <code>feature_dev/.../&lt;dev&gt;</code>；其他与 <code>branch</code> 同值）</td></tr><tr><td><code>branch_workspace</code></td><td>string</td><td style="text-align:center;">✅</td><td>实际编码分支（= <code>branch</code> 或 <code>branch_dev</code>，步骤 4.5 优先读此字段）</td></tr><tr><td><code>has_dev_branch</code></td><td>boolean</td><td style="text-align:center;"></td><td>仅 feature/ 场景为 <code>true</code>（步骤 4.5 父孙等价检查的开关）</td></tr><tr><td><code>branch_status</code></td><td>string</td><td style="text-align:center;"></td><td><code>auto_recommended</code> / <code>user_modified</code> / <code>user_specified</code> / <code>iteration_reuse</code></td></tr><tr><td><code>task_id</code></td><td>string</td><td style="text-align:center;"></td><td>任务平台 ID</td></tr><tr><td><code>project</code></td><td>string</td><td style="text-align:center;">✅</td><td>当前活跃项目路径（跨项目场景取当前编码项目路径，与文件名中的 <code>crossProject</code> 标识互补；A↔B 切换时同步更新）</td></tr><tr><td><code>start_time</code></td><td>string</td><td style="text-align:center;">✅</td><td>ISO 8601</td></tr><tr><td><code>steps</code></td><td>object</td><td style="text-align:center;">✅</td><td>各步骤状态映射，key=步骤号，value=<code>{ status, time }</code></td></tr><tr><td><code>signals</code></td><td>array</td><td style="text-align:center;"></td><td>条件激活信号（详见 <code>references/_index.md</code> §条件激活矩阵）</td></tr><tr><td><code>batch_mode</code> / <code>current_batch</code> / <code>total_batches</code> / <code>batches</code></td><td>mixed</td><td style="text-align:center;"></td><td>仅分批执行场景</td></tr><tr><td><code>cross_project</code></td><td>object</td><td style="text-align:center;"></td><td>仅跨项目场景，子字段见模板</td></tr><tr><td><code>doc_platform_tech_proposal</code></td><td>object</td><td style="text-align:center;"></td><td>步骤 4 · 文档决策（环节 3/4） 决策结果，子字段见模板</td></tr><tr><td><code>validation_log</code></td><td>array</td><td style="text-align:center;"></td><td>步骤机器校验摘要（实际产出在 <code>.validated.json</code>）</td></tr><tr><td><code>change_requests</code></td><td>array</td><td style="text-align:center;"></td><td>轻量 CR 追踪（drift-handling 自动创建，步骤 5.5 联动标记 done）</td></tr><tr><td><code>artifacts</code></td><td>object</td><td style="text-align:center;">✅</td><td><strong>需求关联产物索引</strong>：统一记录 plan/devlog/knowledge/metrics/tech_proposal/flow_lock 等分散目录文件的路径</td></tr><tr><td><code>artifacts.dir</code></td><td>string</td><td style="text-align:center;">✅</td><td>dev-logs 目录绝对路径（步骤 4 创建时写入）</td></tr><tr><td><code>artifacts.plan</code></td><td>string</td><td style="text-align:center;">✅</td><td>plan.md 绝对路径（步骤 4 落盘时写入）</td></tr><tr><td><code>artifacts.devlog</code></td><td>string | null</td><td style="text-align:center;">🟡</td><td>devlog.md 路径（步骤 7 H.2 后回填；之前为 null）</td></tr><tr><td><code>artifacts.doc_platform.file_path</code></td><td>string</td><td style="text-align:center;">🟡</td><td>技术方案文档文件路径（文档决策后回填）</td></tr><tr><td><code>artifacts.doc_platform.url</code></td><td>string</td><td style="text-align:center;">🟡</td><td>文档链接（如已发布到在线平台）</td></tr><tr><td><code>artifacts.flow_lock</code></td><td>string</td><td style="text-align:center;">✅</td><td>.flow 锁文件绝对路径（阶段 0 创建时写入）</td></tr><tr><td><code>artifacts.knowledge</code></td><td>array</td><td style="text-align:center;">🟡</td><td>关联 knowledge 条目路径（步骤 7 H.3 后回填）</td></tr><tr><td><code>artifacts.metrics</code></td><td>string | null</td><td style="text-align:center;">🟢</td><td>度量报告路径（步骤 7 I / 步骤 9 后回填）</td></tr><tr><td><code>artifacts.flow_report</code></td><td>string | null</td><td style="text-align:center;">🟢</td><td>复盘报告路径（步骤 7 I / 步骤 9 后回填）</td></tr><tr><td><code>sync_history</code></td><td>array</td><td style="text-align:center;"></td><td>dev:sync 历史记录（at / from_step / choice）</td></tr></tbody></table><h3 id="_2-1-steps-n-status-取值" tabindex="-1">2.1 <code>steps.{N}.status</code> 取值 <a class="header-anchor" href="#_2-1-steps-n-status-取值" aria-label="Permalink to &quot;2.1 `steps.{N}.status` 取值&quot;">​</a></h3><table tabindex="0"><thead><tr><th>值</th><th>含义</th><th style="text-align:center;">emoji</th></tr></thead><tbody><tr><td><code>pending</code></td><td>待执行</td><td style="text-align:center;">⏸️</td></tr><tr><td><code>in_progress</code></td><td>执行中</td><td style="text-align:center;">🔄</td></tr><tr><td><code>completed</code></td><td>已完成</td><td style="text-align:center;">✅</td></tr><tr><td><code>partial</code></td><td>部分完成</td><td style="text-align:center;">⚠️</td></tr><tr><td><code>skipped</code></td><td>跳过</td><td style="text-align:center;">❌</td></tr></tbody></table><h3 id="_2-2-头部更新规则-每步骤完成钩子必做" tabindex="-1">2.2 头部更新规则（每步骤完成钩子必做） <a class="header-anchor" href="#_2-2-头部更新规则-每步骤完成钩子必做" aria-label="Permalink to &quot;2.2 头部更新规则（每步骤完成钩子必做）&quot;">​</a></h3><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 步骤 N 完成后：</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">current_step</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">N+1</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">steps</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">N</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">status</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">completed</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">time</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;MM-DD HH:mm&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">N+1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">status</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">in_progress</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre></div><p>流程完成时：<code>status: completed</code> + <code>current_step: done</code>，所有步骤 status ∈ {completed, partial, skipped}。</p><h3 id="_2-3-artifacts-回填规则-每步骤完成钩子-与-§2-2-同步执行" tabindex="-1">2.3 artifacts 回填规则（每步骤完成钩子，与 §2.2 同步执行） <a class="header-anchor" href="#_2-3-artifacts-回填规则-每步骤完成钩子-与-§2-2-同步执行" aria-label="Permalink to &quot;2.3 artifacts 回填规则（每步骤完成钩子，与 §2.2 同步执行）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>步骤/环节</th><th>回填字段</th><th>写入内容</th><th style="text-align:center;">校验</th></tr></thead><tbody><tr><td>阶段 0</td><td><code>artifacts.flow_lock</code></td><td>.flow 锁文件绝对路径</td><td style="text-align:center;"><code>[ -f ]</code></td></tr><tr><td>步骤 4</td><td><code>artifacts.dir</code></td><td>dev-logs 目录绝对路径</td><td style="text-align:center;"><code>[ -d ]</code></td></tr><tr><td>步骤 4</td><td><code>artifacts.plan</code></td><td>plan.md 绝对路径（与 <code>plan_saved_to_disk</code> 同步）</td><td style="text-align:center;"><code>[ -f ]</code></td></tr><tr><td>步骤 4 (文档决策)</td><td><code>artifacts.doc_platform.file_path</code> / <code>artifacts.doc_platform.url</code></td><td>与 <code>doc_platform_tech_proposal</code> 同步</td><td style="text-align:center;">非空检查</td></tr><tr><td>步骤 7 H.2</td><td><code>artifacts.devlog</code></td><td>devlog.md 绝对路径（null → 路径）</td><td style="text-align:center;"><code>[ -f ]</code></td></tr><tr><td>步骤 7 H.3</td><td><code>artifacts.knowledge</code></td><td>关联 knowledge 条目路径数组</td><td style="text-align:center;">数组非空</td></tr><tr><td>步骤 7 I</td><td><code>artifacts.metrics</code></td><td>度量报告 .yaml 路径</td><td style="text-align:center;"><code>[ -f ]</code></td></tr><tr><td>步骤 7 I</td><td><code>artifacts.flow_report</code></td><td>复盘报告 .html 路径</td><td style="text-align:center;"><code>[ -f ]</code></td></tr><tr><td>dev:sync</td><td>全量路径</td><td>遍历所有非 null 路径确认存在</td><td style="text-align:center;">失效标注 ⚠️</td></tr></tbody></table><p><strong>红线</strong>：❌ 步骤 4 完成时 <code>artifacts.dir</code>、<code>artifacts.plan</code>、<code>artifacts.flow_lock</code> 任一为空或路径不存在 → 拒绝进入步骤 4.5； ❌ 步骤 7 完成时 <code>artifacts.devlog</code> 仍为 null（标准执行）→ 拒绝标记流程完成。</p><hr><h2 id="三、markdown-正文必填区块" tabindex="-1">三、Markdown 正文必填区块 <a class="header-anchor" href="#三、markdown-正文必填区块" aria-label="Permalink to &quot;三、Markdown 正文必填区块&quot;">​</a></h2><table tabindex="0"><thead><tr><th>区块</th><th style="text-align:center;">必填</th><th>用途</th></tr></thead><tbody><tr><td><code>## 需求</code></td><td style="text-align:center;">✅</td><td>任务平台（含完整可点击 URL）+ 标题 + 摘要 + 分支 + 项目 + 参考</td></tr><tr><td><code>## 项目与分支汇总</code></td><td style="text-align:center;">✅</td><td>单/多项目角色、分支、workspace 路径、改动文件数、状态</td></tr><tr><td><code>## 变更动机</code></td><td style="text-align:center;"></td><td>复杂需求建议填（业务背景、期望效果、不做的后果）</td></tr><tr><td><code>## 约束与决策</code></td><td style="text-align:center;">✅</td><td>时间戳条目，<strong>追加不删</strong>；决策推翻用 <code>~~删除线~~</code> + 关联新条目</td></tr><tr><td><code>## 计划</code></td><td style="text-align:center;">✅</td><td>步骤 4 锁定后不可改，仅更新状态标记</td></tr><tr><td><code>## 范围</code></td><td style="text-align:center;">✅</td><td>涉及文件清单 + 上下游影响</td></tr><tr><td><code>## 进度</code></td><td style="text-align:center;">✅</td><td>「当前状态」一句话 + 「步骤清单」表格 + 「恢复指令」3 段式</td></tr><tr><td><code>## 备注</code></td><td style="text-align:center;"></td><td>子章节化（参考实现 / 数据结构 / 组件行为 / 关键调用 / 接口协议 / UI 要点）</td></tr></tbody></table><h3 id="_3-1-恢复指令-3-段式硬化-schema-v3" tabindex="-1">3.1 <code>### 恢复指令</code> 3 段式硬化 schema（v3） <a class="header-anchor" href="#_3-1-恢复指令-3-段式硬化-schema-v3" aria-label="Permalink to &quot;3.1 `### 恢复指令` 3 段式硬化 schema（v3）&quot;">​</a></h3><p>必含 3 段子项，与 <code>.flow.recovery</code> 字段语义同步：</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">### 恢复指令</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-light-font-weight:bold;--shiki-dark:#E1E4E8;--shiki-dark-font-weight:bold;"> **昨天/上次我们做了什么**</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">（yesterday）：{1 句 ≤50 字}</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-light-font-weight:bold;--shiki-dark:#E1E4E8;--shiki-dark-font-weight:bold;"> **今天/下一步准备做什么**</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">（next_action）：{1 句可执行}</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-light-font-weight:bold;--shiki-dark:#E1E4E8;--shiki-dark-font-weight:bold;"> **待确认**</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">（pending，无则整项删除）：{≤30 字 列表}</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-light-font-weight:bold;--shiki-dark:#E1E4E8;--shiki-dark-font-weight:bold;"> **模式文件**</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">：{完整/快速}模式</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-light-font-weight:bold;--shiki-dark:#E1E4E8;--shiki-dark-font-weight:bold;"> **注意事项**</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">（可选）：补齐项 / 已知瑕疵</span></span></code></pre></div><p>❌ 禁止仅写一句&quot;从步骤 N 继续&quot;的散文。</p><h3 id="_3-2-备注子章节格式-按需选用" tabindex="-1">3.2 备注子章节格式（按需选用） <a class="header-anchor" href="#_3-2-备注子章节格式-按需选用" aria-label="Permalink to &quot;3.2 备注子章节格式（按需选用）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>子章节</th><th>格式</th></tr></thead><tbody><tr><td><code>### 参考实现</code></td><td>表格：参考对象 | 位置 | 行号</td></tr><tr><td><code>### 数据结构</code></td><td>列表：<code>`变量名`（说明）：`{ 字段 }`</code></td></tr><tr><td><code>### 组件行为</code></td><td>列表：<code>`组件名` + 行为描述</code></td></tr><tr><td><code>### 关键调用</code></td><td>表格：函数/接口 | 签名/路径 | 说明</td></tr><tr><td><code>### 接口协议</code></td><td>代码块或表格</td></tr><tr><td><code>### UI 要点</code></td><td>列表</td></tr></tbody></table><p><strong>红线</strong>：❌ 禁止纯文本流水账；✅ 文件位置必须按 AI 行为规范用反引号包裹相对路径（<code>`相对路径`</code> L行号）。</p><hr><h2 id="四、阶段感知区块-按-phase-必填-v3-2026-05-12" tabindex="-1">四、阶段感知区块（按 phase 必填，v3，2026-05-12） <a class="header-anchor" href="#四、阶段感知区块-按-phase-必填-v3-2026-05-12" aria-label="Permalink to &quot;四、阶段感知区块（按 phase 必填，v3，2026-05-12）&quot;">​</a></h2><blockquote><p><strong>设计意图</strong>：跨天恢复时，编码 / 联调 / 迭代阶段需要的核心信息完全不同，通用模板的 <code>## 进度</code> <code>## 范围</code> 不够。 进入对应 phase 时<strong>新增</strong>对应区块；切出阶段时区块<strong>保留作历史档案</strong>，不删除。</p></blockquote><h3 id="_4-1-编码进度细节-仅-phase-coding" tabindex="-1">4.1 <code>## 编码进度细节</code>（仅 <code>phase: coding</code>） <a class="header-anchor" href="#_4-1-编码进度细节-仅-phase-coding" aria-label="Permalink to &quot;4.1 `## 编码进度细节`（仅 `phase: coding`）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>子项</th><th style="text-align:center;">必填</th><th>内容</th></tr></thead><tbody><tr><td>已改文件 + 状态</td><td style="text-align:center;">✅</td><td>表格：文件 | 改动摘要 | 状态（已改/已撤销/已 commit）—— working tree 真实快照</td></tr><tr><td>未完成 todo</td><td style="text-align:center;">✅</td><td>列表，每项 ≤30 字</td></tr><tr><td>上次 lint/build 状态</td><td style="text-align:center;"></td><td>&quot;0 lint error / build pass / 测试未跑&quot;</td></tr><tr><td>当前 commit 基准</td><td style="text-align:center;"></td><td>7 位 hash + commit message（24h+ 对账用）</td></tr></tbody></table><h3 id="_4-2-联调暂存-仅-phase-integration" tabindex="-1">4.2 <code>## 联调暂存</code>（仅 <code>phase: integration</code>） <a class="header-anchor" href="#_4-2-联调暂存-仅-phase-integration" aria-label="Permalink to &quot;4.2 `## 联调暂存`（仅 `phase: integration`）&quot;">​</a></h3><p>记录&quot;联调临时改动、结束后必须恢复&quot;的清单（历史上脏代码进 master 的重灾区）：</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">|#|改动位置|改动内容|恢复方式|状态|</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">|---|---|---|---|:---:|</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">|1|</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">`src/utils/env.ts`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> L42|强制开启灰度|改回 </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">`getGray(&#39;xxx&#39;)`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">|⏸️|</span></span></code></pre></div><p>附 <code>### 联调 Checklist</code>（接口契约 / 灰度配置 / 错误码 / 跨域 cookie）。</p><h3 id="_4-3-迭代轮次详情-仅-phase-iteration" tabindex="-1">4.3 <code>## 迭代轮次详情</code>（仅 <code>phase: iteration</code>） <a class="header-anchor" href="#_4-3-迭代轮次详情-仅-phase-iteration" aria-label="Permalink to &quot;4.3 `## 迭代轮次详情`（仅 `phase: iteration`）&quot;">​</a></h3><p>每轮迭代追加 <code>### 第N轮（YYYY-MM-DD ~ YYYY-MM-DD）</code> 子节，已有轮次保留作档案。每轮含：反馈来源 / 反馈原文（不改写） / 本轮范围 / 已通过用例 / 未通过用例 / 状态。</p><p><strong>轮次膨胀控制</strong>：当前轮次完整保留；旧轮次新增下一轮时<strong>主动压缩</strong>为 1-2 行摘要。</p><h3 id="_4-4-阶段切换写入规则" tabindex="-1">4.4 阶段切换写入规则 <a class="header-anchor" href="#_4-4-阶段切换写入规则" aria-label="Permalink to &quot;4.4 阶段切换写入规则&quot;">​</a></h3><table tabindex="0"><thead><tr><th>切换</th><th>触发</th><th>必做</th></tr></thead><tbody><tr><td><code>research</code> → <code>coding</code></td><td>步骤 5 开始</td><td>创建 <code>## 编码进度细节</code>，从 <code>## 范围</code> 复制初始文件清单</td></tr><tr><td><code>coding</code> → <code>integration</code></td><td>用户说&quot;开始联调&quot; / 6A 进入接口验证</td><td>创建 <code>## 联调暂存</code>（默认空表）</td></tr><tr><td><code>integration</code> → <code>coding</code></td><td>联调发现需要补改代码</td><td><code>## 联调暂存</code> 保留，回 <code>## 编码进度细节</code> 继续</td></tr><tr><td>任意 → <code>iteration</code></td><td>检测到迭代信号</td><td>创建/追加 <code>## 迭代轮次详情</code> 新 <code>### 第N轮</code></td></tr><tr><td>任意 → <code>commit-archive</code></td><td>步骤 7（commit/devlog/knowledge）</td><td>不强制新建，但所有阶段区块的&quot;待恢复/未完成&quot;项必须清零</td></tr></tbody></table><p><strong><code>.flow.phase</code> 同步</strong>：阶段切换时<strong>必须</strong>同步更新 <code>.flow.phase</code>，与工作上下文区块保持一致。</p><hr><h2 id="五、创建-更新决策流程-最高优先级" tabindex="-1">五、创建/更新决策流程（最高优先级） <a class="header-anchor" href="#五、创建-更新决策流程-最高优先级" aria-label="Permalink to &quot;五、创建/更新决策流程（最高优先级）&quot;">​</a></h2><blockquote><p><strong>核心原则</strong>：同一需求只允许一个工作上下文文件，必须复用已有文件而非每次新建。</p></blockquote><h3 id="_5-1-强制执行流程-4-步" tabindex="-1">5.1 强制执行流程（4 步） <a class="header-anchor" href="#_5-1-强制执行流程-4-步" aria-label="Permalink to &quot;5.1 强制执行流程（4 步）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>步骤</th><th>动作</th></tr></thead><tbody><tr><td>0</td><td><strong>加载模板</strong></td><td>创建新文件前必须 <code>read_file(&quot;references/templates/working-context.tpl.md&quot;)</code>，禁止凭记忆填写</td></tr><tr><td>1</td><td><strong>扫描已有</strong></td><td><code>ls /Users/{username}/.codebuddy/working-context/</code></td></tr><tr><td>2</td><td><strong>匹配同一需求</strong></td><td>按需求简述 / 任务平台 ID / 分支名 / 项目路径任一维度命中即视为同一需求</td></tr><tr><td>3</td><td><strong>决策</strong></td><td>1 个匹配→更新；多个匹配→选最完整 1 个；无匹配→创建新文件</td></tr></tbody></table><h3 id="_5-2-创建-更新后必校验" tabindex="-1">5.2 创建/更新后必校验 <a class="header-anchor" href="#_5-2-创建-更新后必校验" aria-label="Permalink to &quot;5.2 创建/更新后必校验&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.codebuddy/skills/dev-flow/scripts/validate-working-context.sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">文件路</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">径</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 返回非 0 → 修正后重试</span></span></code></pre></div><p>校验项（脚本完整实现）：① 文件名格式 ② YAML 头闭合+必填字段 ③ 必填区块（<code>## 需求</code> 含 任务平台 URL、<code>## 进度</code> 等）④ <code>.flow</code> 一致性。</p><h3 id="_5-3-更新已有文件规则" tabindex="-1">5.3 更新已有文件规则 <a class="header-anchor" href="#_5-3-更新已有文件规则" aria-label="Permalink to &quot;5.3 更新已有文件规则&quot;">​</a></h3><ol><li><strong>先 <code>read_file</code> 读取完整内容</strong></li><li><strong>同步 YAML 头部</strong>：刷新 <code>current_step</code> / 对应步骤 <code>status</code> <code>time</code> / 流程状态变更刷 <code>status</code> / 迭代修复递增 <code>iteration</code></li><li><strong>Markdown 正文增量更新，不覆盖</strong>：</li></ol><ul><li><code>## 约束与决策</code>：追加不删；决策推翻用 <code>~~删除线~~</code> + 关联新条目</li><li><code>## 计划</code>：锁定后不修改</li><li><code>## 范围</code>：新文件追加到表格末尾</li><li><code>## 进度</code>：「当前状态」覆盖更新；「步骤清单」增量更新；「恢复指令」覆盖更新（必含 3 段式）</li><li><code>## 备注</code>：追加，不删除</li></ul><ol><li><strong>跨 Skill 操作回写</strong>（如 doc-platform-doc 更新文档后）：必须立即回写工作上下文进度区块和 YAML 头部，<strong>优先级高于&quot;展示结果后结束&quot;</strong>——Skill 流程到最后一步仍必须回写后才算真正完成。</li></ol><ul><li><strong>文档操作专项</strong>：文档创建成功 → 写 <code>file_path</code>/<code>locked_title</code>/<code>status: synced</code> + <code>action_history</code> 追加 <code>created</code>；文档更新 → 刷 <code>last_synced_at</code> + 追加 <code>updated</code>；失败 → <code>status: failed</code> + 备注详情。</li></ul><ol><li><strong>更新头部时间戳</strong>（不改文件名，文件名日期=创建日期）</li></ol><h3 id="_5-4-迭代修复场景额外规则" tabindex="-1">5.4 迭代修复场景额外规则 <a class="header-anchor" href="#_5-4-迭代修复场景额外规则" aria-label="Permalink to &quot;5.4 迭代修复场景额外规则&quot;">​</a></h3><ul><li>YAML <code>iteration</code> 递增</li><li><code>## 约束与决策</code> 和 <code>## 进度</code> 用 <code>【第N轮】</code> 标签区分轮次</li><li><code>## 范围</code> 表格新增文件标 <code>【第N轮新增】</code></li><li>上一轮计划状态改为 <code>已完成</code>，本轮新增独立计划段</li><li>文件超 200 行时精简早期轮次为一行摘要</li></ul><h3 id="_5-5-禁止行为" tabindex="-1">5.5 禁止行为 <a class="header-anchor" href="#_5-5-禁止行为" aria-label="Permalink to &quot;5.5 禁止行为&quot;">​</a></h3><ul><li>❌ 不扫描就直接创建新文件</li><li>❌ 同一需求创建多个文件（不同日期）</li><li>❌ 更新时覆盖已有「约束与决策」/「范围」条目</li><li>❌ 因「找不到」就新建（必须先扫描）</li><li>❌ 创建时不先读模板</li><li>❌ 创建/更新后不做校验</li><li>❌ 更新 Markdown 但不同步 YAML 头部</li></ul><hr><h2 id="六、项目缩写映射" tabindex="-1">六、项目缩写映射 <a class="header-anchor" href="#六、项目缩写映射" aria-label="Permalink to &quot;六、项目缩写映射&quot;">​</a></h2><blockquote><p>工作上下文文件名格式：<code>{YYYYMMDD}_{需求简述}_{项目缩写}.md</code></p><p>项目缩写由 <code>config/org.yaml</code> 的 <code>project_name</code> 字段决定。多项目场景下可自定义映射， 脚本 <code>validate-working-context.sh</code> 从配置中读取白名单。</p><p>默认已知缩写：<code>my-project</code>、<code>my-lib</code>、<code>my-components</code>、<code>my-app</code>、<code>my-service</code>。</p></blockquote><hr><h2 id="七、需求漂移处理子流程" tabindex="-1">七、需求漂移处理子流程 <a class="header-anchor" href="#七、需求漂移处理子流程" aria-label="Permalink to &quot;七、需求漂移处理子流程&quot;">​</a></h2><blockquote><p>⚙️ <strong>单一权威源</strong>（2026-05-19 迁移）：完整规则（设计意图 / 触发条件 / 三步固定动作 / 反模式 / 与既有机制对照表）→ <code>references/drift-handling.md</code>。 📌 本子流程刷新动作复用的「<code>## 约束与决策</code> 删除线规范」定义在本文件 §五.3。</p></blockquote><hr><h2 id="八、活跃流程注册目录-active-flows" tabindex="-1">八、活跃流程注册目录（<code>.active-flows/</code>） <a class="header-anchor" href="#八、活跃流程注册目录-active-flows" aria-label="Permalink to &quot;八、活跃流程注册目录（`.active-flows/`）&quot;">​</a></h2><blockquote><p><strong>完整规范</strong>（目录结构、<code>.flow</code> v3 schema、字段语义、<code>status</code> 枚举、生命周期、智能恢复网关、并发抢占、降级行为）→ <code>references/active-flows.md</code>（2026-05-19 拆分）。 <strong>何时加载</strong>：跨会话恢复 / 步骤完成钩子刷新 <code>.flow</code> / 用户询问活跃需求清理。</p></blockquote><hr><h2 id="九、目录结构禁令-2026-06-02-事故反思新增" tabindex="-1">九、目录结构禁令（2026-06-02 事故反思新增） <a class="header-anchor" href="#九、目录结构禁令-2026-06-02-事故反思新增" aria-label="Permalink to &quot;九、目录结构禁令（2026-06-02 事故反思新增）&quot;">​</a></h2><blockquote><p>🔴 <strong>dev-flow 不存在自动归档机制</strong>。<code>~/.codebuddy/working-context/</code> 目录结构是 dev-flow 全套 lint 与 dashboard 的隐式契约，AI 不得擅自破坏。 <strong>加载触发</strong>：dev-flow 流程激活（已通过 SKILL.md 加载）；执行 working-context 目录内 <code>mv</code> 操作前；用户说&quot;清理/归档/整理&quot;工作上下文时。</p></blockquote><h3 id="_9-1-禁止动作" tabindex="-1">9.1 禁止动作 <a class="header-anchor" href="#_9-1-禁止动作" aria-label="Permalink to &quot;9.1 禁止动作&quot;">​</a></h3><ul><li>❌ <code>mv ~/.codebuddy/working-context/&lt;slug&gt;.md ~/.codebuddy/working-context/archive/...</code>（误归档 .md）</li><li>❌ <code>mv ~/.codebuddy/working-context/.active-flows/&lt;slug&gt;.flow ~/.codebuddy/working-context/archive/...</code>（应该 <code>rm</code> 不是 <code>mv</code>）</li><li>❌ 创建 <code>~/.codebuddy/working-context/archive/</code> 子目录（dev-flow 全套规范无该路径定义）</li><li>❌ 流程结束时只删 <code>.flow</code> 不清 <code>.active-flows/&lt;slug&gt;.step-*.validated*</code> 残留（违反 <code>references/active-flows.md</code> §锁文件维护规则）</li></ul><h3 id="_9-2-设计理由" tabindex="-1">9.2 设计理由 <a class="header-anchor" href="#_9-2-设计理由" aria-label="Permalink to &quot;9.2 设计理由&quot;">​</a></h3><ol><li><strong>lint 隐式契约</strong>：<code>working-context-freshness-lint.sh</code> / <code>validate-output.sh §P2</code> / <code>validate-working-context.sh</code> / <code>gen-dashboard.py</code> 等 4+ 处脚本都用 <code>[ -f working-context/&lt;slug&gt;.md ]</code> 模式定位文件，被 mv 走后会<strong>沉默跳过</strong>而非报错</li><li><strong>dev-flow 步骤 10 收尾规范</strong>：<code>steps/step-8-10-full.md</code> L474 明确&quot;<code>.md</code> 文件保留，仅删 <code>.flow</code> 锁文件&quot;</li><li><strong>跨会话恢复机制</strong>：智能恢复网关只扫顶层 <code>working-context/*.md</code>，归档后失联</li></ol><h3 id="_9-3-reflex-自动触发" tabindex="-1">9.3 Reflex（自动触发） <a class="header-anchor" href="#_9-3-reflex-自动触发" aria-label="Permalink to &quot;9.3 Reflex（自动触发）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>触发信号</th><th>动作</th></tr></thead><tbody><tr><td>用户说&quot;清理已完成需求 / 归档老需求 / 让 working-context 干净一点&quot;</td><td>不得默认走 mv，必须先询问「<code>rm</code> 删除 还是 保留」；如要&quot;批量按月归档&quot;，必须先扩展 dev-flow 自动归档规范（无人做过）</td></tr><tr><td>检测到 <code>~/.codebuddy/working-context/archive/</code> 存在且含 <code>.md</code> 文件</td><td>必须主动报告异常，不视为正常状态</td></tr><tr><td>即将执行 working-context 内 <code>mv</code> 操作</td><td>操作前先用 <code>bash ~/.codebuddy/skills/dev-flow/scripts/lints/working-context-location-lint.sh --all</code> 体检</td></tr></tbody></table><h3 id="_9-4-违反后的自动捕获-2026-06-02-已实施" tabindex="-1">9.4 违反后的自动捕获（2026-06-02 已实施） <a class="header-anchor" href="#_9-4-违反后的自动捕获-2026-06-02-已实施" aria-label="Permalink to &quot;9.4 违反后的自动捕获（2026-06-02 已实施）&quot;">​</a></h3><ul><li><code>scripts/hooks/post-step.sh</code> 步骤 7 / 10 完成后自动调用 <code>working-context-location-lint.sh</code>， 4 项检查（L1 位置 / L2 状态一致性 / L3 <code>.active-flows</code> 残留 / L4 archive 中 .md 检测）失败即 block</li><li><code>scripts/lints/working-context-freshness-lint.sh</code> 步骤 5.5 / 7 时也兜底检测 <code>archive/</code> 路径，发现误归档立即 <code>exit 1</code></li><li><code>scripts/validate-output.sh §step10 P2</code> 同步改造，文件不存在时不再静默跳过</li><li>单一权威源：<code>config/gates.yaml §lints.working-context-location-lint</code></li></ul>',92)])])}const k=e(s,[["render",i]]);export{g as __pageData,k as default};
